const WEEK8_CODES = {
  topic1: {
    title: "First-Order Dynamics & FOPDT Fitting",
    python: "# Week 8 - Topic 1: Stirred-Tank Heating -> First-Order Process & FOPDT Fitting\n# Lecture (Part 1): energy balance on a stirred tank with holdup V,\n#   rho*V*cp dT'/dt = mdot*cp (Tin' - T') + Q'\n# In deviation variables and Laplace space,\n#   T'(s) = [K/(tau s + 1)] Q'(s) + [1/(tau s + 1)] Tin'(s),\n#   K = 1/(mdot*cp),  tau = rho*V/mdot.\n# With a transport delay theta_p (dead time), the FOPDT model is\n#   G(s) = Kp exp(-theta_p s) / (tau_p s + 1).\n# Two-point fitting (lecture): find t1, t2 where y/y_inf = 0.283 and 0.632:\n#   tau_p = 3*(t2 - t1)/2,   theta_p = (3*t1 - t2)/2.\n# Lecture example: t1 = 21.8 s, t2 = 36.0 s -> tau_p = 21.3 s, theta_p = 14.7 s.\n\nimport math\n\n\ndef fopdt_step(t, Kp, du, tau_p, theta_p, y0=0.0):\n    \"\"\"Step response of Kp*exp(-theta_p*s)/(tau_p*s+1) to a step du at t = 0.\"\"\"\n    if t < theta_p:\n        return y0\n    e = math.exp(-(t - theta_p) / tau_p)\n    return e * y0 + (1.0 - e) * Kp * du\n\n\ndef two_point_fit(t1, t2):\n    \"\"\"FOPDT parameters from the 28.3% and 63.2% response times.\"\"\"\n    tau_p = 3.0 * (t2 - t1) / 2.0\n    theta_p = (3.0 * t1 - t2) / 2.0\n    return tau_p, theta_p\n\n\nif __name__ == \"__main__\":\n    # --- stirred tank: physical parameters -> K and tau ---\n    rho, cp = 1000.0, 4184.0          # water, SI\n    V, mdot = 0.5, 0.25               # m^3, kg/s\n    K = 1.0 / (mdot * cp)             # K per W\n    tau = rho * V / mdot              # s\n    print(\"Stirred-tank first-order parameters:\")\n    print(f\"  K   = 1/(mdot*cp) = {K:.3e} K/W\")\n    print(f\"  tau = rho*V/mdot  = {tau:.1f} s\")\n    print(f\"  (a +10 kW step in Q raises T by K*dQ = {K*1e4:.3f} K at steady state)\")\n\n    # --- lecture two-point fit ---\n    t1, t2 = 21.8, 36.0\n    tau_p, theta_p = two_point_fit(t1, t2)\n    print(\"\\nFOPDT two-point fit (lecture valve-to-temperature data):\")\n    print(f\"  t1 = {t1} s (y/y_inf = 0.283), t2 = {t2} s (y/y_inf = 0.632)\")\n    print(f\"  tau_p   = 3(t2-t1)/2 = {tau_p:.1f} s   (lecture: 21.3)\")\n    print(f\"  theta_p = (3t1-t2)/2 = {theta_p:.1f} s   (lecture: 14.7)\")\n\n    # verify: the fitted model reproduces the two anchor fractions exactly\n    for tt, target in [(t1, 1 - math.exp(-1.0 / 3.0)), (t2, 1 - math.exp(-1.0))]:\n        y = fopdt_step(tt, 1.0, 1.0, tau_p, theta_p)\n        print(f\"  check y({tt:5.1f})/y_inf = {y:.4f}  (target {target:.4f})\")\n\n    # --- normalized step-response table ---\n    print(\"\\nNormalized FOPDT step response (Kp*du = 1):\")\n    print(\"    t (s)    y(t)\")\n    for tt in range(0, 121, 10):\n        print(f\"  {tt:6.0f}   {fopdt_step(tt, 1.0, 1.0, tau_p, theta_p):7.4f}\")\n    print(\"  -> y = 0 until t = theta_p, then rises with time constant tau_p;\")\n    print(\"     63.2% of the final value is reached at t = theta_p + tau_p \"\n          f\"= {theta_p + tau_p:.1f} s.\")\n",
    matlab: "% Week 8 - Topic 1: Stirred-Tank Heating -> First-Order Process & FOPDT Fitting\n% Energy balance: rho*V*cp dT'/dt = mdot*cp (Tin' - T') + Q'\n%   -> T'(s) = [K/(tau s+1)] Q'(s) + [1/(tau s+1)] Tin'(s),\n%      K = 1/(mdot*cp), tau = rho*V/mdot.\n% FOPDT: G(s) = Kp exp(-theta_p s)/(tau_p s + 1).\n% Two-point fit: tau_p = 3(t2-t1)/2, theta_p = (3 t1 - t2)/2\n% Lecture example: t1 = 21.8 s, t2 = 36.0 s -> tau_p = 21.3 s, theta_p = 14.7 s.\n\nclear; clc;\n\n% --- stirred tank: physical parameters -> K and tau ---\nrho = 1000; cp = 4184; V = 0.5; mdot = 0.25;\nK = 1/(mdot*cp); tau = rho*V/mdot;\nfprintf('Stirred-tank first-order parameters:\\n');\nfprintf('  K   = 1/(mdot*cp) = %.3e K/W\\n', K);\nfprintf('  tau = rho*V/mdot  = %.1f s\\n', tau);\nfprintf('  (a +10 kW step in Q raises T by %.3f K at steady state)\\n\\n', K*1e4);\n\n% --- lecture two-point fit ---\nt1 = 21.8; t2 = 36.0;\ntau_p   = 3*(t2 - t1)/2;\ntheta_p = (3*t1 - t2)/2;\nfprintf('FOPDT two-point fit (lecture valve-to-temperature data):\\n');\nfprintf('  t1 = %.1f s (0.283), t2 = %.1f s (0.632)\\n', t1, t2);\nfprintf('  tau_p   = %.1f s (lecture 21.3)\\n', tau_p);\nfprintf('  theta_p = %.1f s (lecture 14.7)\\n', theta_p);\n\n% verify anchor fractions\nfor tt = [t1 t2]\n    y = fopdt_step(tt, 1, 1, tau_p, theta_p);\n    fprintf('  check y(%5.1f)/y_inf = %.4f\\n', tt, y);\nend\n\n% --- normalized step-response table ---\nfprintf('\\nNormalized FOPDT step response (Kp*du = 1):\\n    t (s)    y(t)\\n');\nfor tt = 0:10:120\n    fprintf('  %6.0f   %7.4f\\n', tt, fopdt_step(tt, 1, 1, tau_p, theta_p));\nend\nfprintf('  -> 63.2%% reached at theta_p + tau_p = %.1f s\\n', theta_p + tau_p);\n\nfunction y = fopdt_step(t, Kp, du, tau_p, theta_p)\n    if t < theta_p\n        y = 0;\n    else\n        y = (1 - exp(-(t - theta_p)/tau_p)) * Kp * du;\n    end\nend\n",
    julia: "# Week 8 - Topic 1: Stirred-Tank Heating -> First-Order Process & FOPDT Fitting\n# Energy balance: rho*V*cp dT'/dt = mdot*cp (Tin' - T') + Q'\n#   -> T'(s) = [K/(tau s+1)] Q'(s) + [1/(tau s+1)] Tin'(s),\n#      K = 1/(mdot*cp), tau = rho*V/mdot.\n# FOPDT: G(s) = Kp exp(-theta_p s)/(tau_p s + 1).\n# Two-point fit: tau_p = 3(t2-t1)/2, theta_p = (3 t1 - t2)/2\n# Lecture example: t1 = 21.8 s, t2 = 36.0 s -> tau_p = 21.3 s, theta_p = 14.7 s.\n\nusing Printf\n\nfunction fopdt_step(t, Kp, du, tau_p, theta_p; y0=0.0)\n    t < theta_p && return y0\n    e = exp(-(t - theta_p) / tau_p)\n    return e * y0 + (1 - e) * Kp * du\nend\n\ntwo_point_fit(t1, t2) = (3 * (t2 - t1) / 2, (3 * t1 - t2) / 2)\n\n# --- stirred tank: physical parameters -> K and tau ---\nrho, cp = 1000.0, 4184.0\nV, mdot = 0.5, 0.25\nK = 1 / (mdot * cp)\ntau = rho * V / mdot\nprintln(\"Stirred-tank first-order parameters:\")\n@printf(\"  K   = 1/(mdot*cp) = %.3e K/W\\n\", K)\n@printf(\"  tau = rho*V/mdot  = %.1f s\\n\", tau)\n@printf(\"  (a +10 kW step in Q raises T by %.3f K at steady state)\\n\\n\", K * 1e4)\n\n# --- lecture two-point fit ---\nt1, t2 = 21.8, 36.0\ntau_p, theta_p = two_point_fit(t1, t2)\nprintln(\"FOPDT two-point fit (lecture valve-to-temperature data):\")\n@printf(\"  t1 = %.1f s (0.283), t2 = %.1f s (0.632)\\n\", t1, t2)\n@printf(\"  tau_p   = %.1f s (lecture 21.3)\\n\", tau_p)\n@printf(\"  theta_p = %.1f s (lecture 14.7)\\n\", theta_p)\nfor tt in (t1, t2)\n    @printf(\"  check y(%5.1f)/y_inf = %.4f\\n\", tt, fopdt_step(tt, 1.0, 1.0, tau_p, theta_p))\nend\n\n# --- normalized step-response table ---\nprintln(\"\\nNormalized FOPDT step response (Kp*du = 1):\\n    t (s)    y(t)\")\nfor tt in 0:10:120\n    @printf(\"  %6d   %7.4f\\n\", tt, fopdt_step(Float64(tt), 1.0, 1.0, tau_p, theta_p))\nend\n@printf(\"  -> 63.2%% reached at theta_p + tau_p = %.1f s\\n\", theta_p + tau_p)\n",
    cpp: "// Week 8 - Topic 1: Stirred-Tank Heating -> First-Order Process & FOPDT Fitting\n// Energy balance: rho*V*cp dT'/dt = mdot*cp (Tin' - T') + Q'\n//   -> T'(s) = [K/(tau s+1)] Q'(s) + [1/(tau s+1)] Tin'(s),\n//      K = 1/(mdot*cp), tau = rho*V/mdot.\n// FOPDT: G(s) = Kp exp(-theta_p s)/(tau_p s + 1).\n// Two-point fit: tau_p = 3(t2-t1)/2, theta_p = (3 t1 - t2)/2\n// Lecture example: t1 = 21.8 s, t2 = 36.0 s -> tau_p = 21.3 s, theta_p = 14.7 s.\n// Build: g++ -O2 -std=c++17 week8_topic1_fopdt.cpp -o fopdt && ./fopdt\n\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n\ndouble fopdt_step(double t, double Kp, double du,\n                  double tau_p, double theta_p, double y0 = 0.0) {\n    if (t < theta_p) return y0;\n    double e = std::exp(-(t - theta_p) / tau_p);\n    return e * y0 + (1.0 - e) * Kp * du;\n}\n\nint main() {\n    // --- stirred tank: physical parameters -> K and tau ---\n    const double rho = 1000.0, cp = 4184.0, V = 0.5, mdot = 0.25;\n    const double K = 1.0 / (mdot * cp);\n    const double tau = rho * V / mdot;\n    std::printf(\"Stirred-tank first-order parameters:\\n\");\n    std::printf(\"  K   = 1/(mdot*cp) = %.3e K/W\\n\", K);\n    std::printf(\"  tau = rho*V/mdot  = %.1f s\\n\", tau);\n    std::printf(\"  (a +10 kW step in Q raises T by %.3f K at steady state)\\n\\n\", K * 1e4);\n\n    // --- lecture two-point fit ---\n    const double t1 = 21.8, t2 = 36.0;\n    const double tau_p = 3.0 * (t2 - t1) / 2.0;\n    const double theta_p = (3.0 * t1 - t2) / 2.0;\n    std::printf(\"FOPDT two-point fit (lecture valve-to-temperature data):\\n\");\n    std::printf(\"  t1 = %.1f s (0.283), t2 = %.1f s (0.632)\\n\", t1, t2);\n    std::printf(\"  tau_p   = %.1f s (lecture 21.3)\\n\", tau_p);\n    std::printf(\"  theta_p = %.1f s (lecture 14.7)\\n\", theta_p);\n    for (double tt : {t1, t2})\n        std::printf(\"  check y(%5.1f)/y_inf = %.4f\\n\", tt,\n                    fopdt_step(tt, 1.0, 1.0, tau_p, theta_p));\n\n    // --- normalized step-response table ---\n    std::printf(\"\\nNormalized FOPDT step response (Kp*du = 1):\\n    t (s)    y(t)\\n\");\n    for (int tt = 0; tt <= 120; tt += 10)\n        std::printf(\"  %6d   %7.4f\\n\", tt,\n                    fopdt_step(tt, 1.0, 1.0, tau_p, theta_p));\n    std::printf(\"  -> 63.2%% reached at theta_p + tau_p = %.1f s\\n\", theta_p + tau_p);\n    return 0;\n}\n",
  },
  topic2: {
    title: "PID Feedback & Feedforward Control",
    python: "# Week 8 - Topic 2: PID Feedback & Feedforward Control of a Heat Exchanger\n# Lecture (Part 1): plant (valve voltage -> tank temperature), FOPDT:\n#   G(s)  = exp(-14.7 s) / (21.3 s + 1)        (Kp = 1)\n#   Gd(s) = exp(-35 s)   / (25 s + 1)          (inflow-temperature disturbance)\n# PI controller C(s) = Kc (1 + 1/(tau_I s)); ITAE tuning:\n#   Kc    = 0.859 (theta_p/tau_p)^-0.977          = 1.2341\n#   tau_I = tau_p/0.674 * (theta_p/tau_p)^0.680   = 24.5582\n# Feedforward: exact  F(s) = -Gd/G = -(21.3 s + 1)/(25 s + 1) exp(-(35-14.7) s),\n# or the static version used by MATLAB's 'heatex' demo (gain -1, delay 25 s).\n# This script simulates the closed loop with a discrete PID\n#   p_k = pbar + Kc [ e_k + (dt/tau_I) sum e_j + (tau_D/dt)(e_k - e_{k-1}) ]\n# and reproduces the lecture plots: setpoint overshoot ~1.26 near t ~ 46 s,\n# and disturbance rejection: FB only ~0.53 peak, static FF + FB ~0.17.\n\nimport math\n\n\ndef simulate(Kc, tau_I, tau_D=0.0, T_end=250.0, dt=0.01,\n             setpoint=1.0, disturb=0.0, feedforward=None):\n    \"\"\"Closed-loop FOPDT simulation; feedforward in (None, 'static', 'leadlag').\n\n    Returns (time, y) lists sampled every 1 s.\"\"\"\n    tau_p, theta_p, Kp = 21.3, 14.7, 1.0        # plant\n    tau_d, theta_d = 25.0, 35.0                  # disturbance path\n    n = int(T_end / dt)\n    dp, dd = int(theta_p / dt), int(theta_d / dt)\n    ubuf = [0.0] * (n + dp + 1)                  # delayed control input\n    dbuf = [0.0] * (n + dd + 1)                  # delayed disturbance\n    # feedforward buffers: static = gain -1 with 25 s delay (heatex demo default);\n    # leadlag = exact -Gd/G = -(tau_p s+1)/(tau_d s+1) exp(-(theta_d-theta_p)s)\n    dff_st = int(25.0 / dt)\n    dff_ll = int((theta_d - theta_p) / dt)\n    fbuf = [0.0] * (n + max(dff_st, dff_ll) + 1)\n    xff = 0.0\n    y = yp = yd = 0.0                            # plant/disturbance first-order states\n    I = 0.0\n    e_prev = setpoint\n    ts, ys = [], []\n    for k in range(n):\n        e = setpoint - y\n        I += e * dt\n        u = Kc * (e + I / tau_I + tau_D * (e - e_prev) / dt)\n        e_prev = e\n        if feedforward == \"static\":\n            fbuf[k + dff_st] = -disturb\n            u += fbuf[k]\n        elif feedforward == \"leadlag\":\n            xff += dt * (disturb - xff) / tau_d                  # 1/(tau_d s+1) d\n            fsig = -(tau_p * (disturb - xff) / tau_d + xff)      # -(tau_p s+1)/(tau_d s+1) d\n            fbuf[k + dff_ll] = fsig\n            u += fbuf[k]\n        ubuf[k + dp] = u\n        dbuf[k + dd] = disturb\n        yp += dt * (-yp + Kp * ubuf[k]) / tau_p\n        yd += dt * (-yd + dbuf[k]) / tau_d\n        y = yp + yd\n        if k % int(1.0 / dt) == 0:\n            ts.append(k * dt)\n            ys.append(y)\n    return ts, ys\n\n\nif __name__ == \"__main__\":\n    # --- ITAE tuning from the FOPDT fit ---\n    tau_p, theta_p = 21.3, 14.7\n    r = theta_p / tau_p\n    Kc = 0.859 * r ** (-0.977)\n    tau_I = tau_p / 0.674 * r ** 0.680\n    print(\"ITAE PI tuning for G = exp(-14.7 s)/(21.3 s + 1):\")\n    print(f\"  Kc    = 0.859 (theta/tau)^-0.977          = {Kc:.4f}   (lecture 1.2341)\")\n    print(f\"  tau_I = tau_p/0.674 * (theta/tau)^0.680   = {tau_I:.4f}  (lecture 24.5582)\")\n\n    # --- setpoint step (lecture: overshoot to ~1.26 near t ~ 46 s) ---\n    ts, ys = simulate(Kc, tau_I, setpoint=1.0)\n    ymax = max(ys)\n    tpk = ts[ys.index(ymax)]\n    print(\"\\nSetpoint step response (PI):\")\n    print(f\"  peak y = {ymax:.3f} at t = {tpk:.0f} s (lecture plot: ~1.26 near 46 s)\")\n    print(f\"  final y(250 s) = {ys[-1]:.4f}  -> no offset (integral action)\")\n\n    # --- P-only control: offset remains (and dead time limits the gain) ---\n    for KcP in (0.5, 1.0, 2.0):\n        _, ysp = simulate(KcP, 1e12, T_end=600.0)   # tau_I -> infinity: P-only\n        off = 1.0 - ysp[-1]\n        print(f\"  P-only Kc = {KcP:3.1f}: y_ss = {ysp[-1]:.3f}, offset = {off:.3f} \"\n              f\"(theory 1/(1+Kc*Kp) = {1/(1+KcP):.3f})\")\n    print(\"  -> P control always leaves offset 1/(1+Kc Kp); raising Kc shrinks it\")\n    print(\"     but the dead time destabilizes the loop well before it vanishes\")\n    print(\"     (here the ultimate gain is Kc ~ 2.9).\")\n\n    # --- disturbance step: feedback vs feedback + feedforward ---\n    print(\"\\nUnit disturbance step (setpoint = 0):\")\n    _, yfb = simulate(Kc, tau_I, setpoint=0.0, disturb=1.0)\n    _, yst = simulate(Kc, tau_I, setpoint=0.0, disturb=1.0, feedforward=\"static\")\n    _, yll = simulate(Kc, tau_I, setpoint=0.0, disturb=1.0, feedforward=\"leadlag\")\n    print(f\"  feedback only          : max |y| = {max(abs(v) for v in yfb):.3f} \"\n          \"(lecture plot ~0.53)\")\n    print(f\"  static FF + FB (heatex): max |y| = {max(abs(v) for v in yst):.3f} \"\n          \"(lecture plot ~0.17)\")\n    print(f\"  exact -Gd/G FF + FB    : max |y| = {max(abs(v) for v in yll):.3f}\")\n    print(\"  -> feedforward acts before the error appears; the static version leaves a\")\n    print(\"     lead-lag mismatch, while the exact F = -Gd/G cancels the disturbance\")\n    print(\"     completely (possible here because theta_d > theta_p keeps F causal).\")\n",
    matlab: "% Week 8 - Topic 2: PID Feedback & Feedforward Control of a Heat Exchanger\n% Plant (valve -> tank temperature), FOPDT: G = exp(-14.7 s)/(21.3 s + 1)\n% Disturbance (inflow temperature):       Gd = exp(-35 s)/(25 s + 1)\n% ITAE PI tuning: Kc = 0.859 (th/ta)^-0.977 = 1.2341,\n%                 tau_I = ta/0.674 (th/ta)^0.680 = 24.5582\n% Discrete PID: p_k = Kc [e_k + (dt/tau_I) sum e_j + (tau_D/dt)(e_k - e_{k-1})]\n% Reproduces: setpoint overshoot ~1.26 near t~46 s; disturbance peak 0.53 (FB)\n% vs 0.17 (static FF + FB, the MATLAB 'heatex' demo configuration).\n\nclear; clc;\n\ntau_p = 21.3; theta_p = 14.7;\nr = theta_p/tau_p;\nKc    = 0.859 * r^(-0.977);\ntau_I = tau_p/0.674 * r^0.680;\nfprintf('ITAE PI tuning for G = exp(-14.7 s)/(21.3 s + 1):\\n');\nfprintf('  Kc = %.4f (lecture 1.2341), tau_I = %.4f (lecture 24.5582)\\n\\n', Kc, tau_I);\n\n% --- setpoint step response (PI) ---\n[ts, ys] = closed_loop(Kc, tau_I, 0, 250, 1, 0, 'none');\n[ymax, im] = max(ys);\nfprintf('Setpoint step (PI): peak y = %.3f at t = %.0f s (lecture ~1.26 @ 46 s)\\n', ...\n        ymax, ts(im));\nfprintf('  final y = %.4f -> no offset (integral action)\\n\\n', ys(end));\n\n% --- P-only: offset remains ---\nfor KcP = [0.5 1 2]\n    [~, yp] = closed_loop(KcP, 1e12, 0, 600, 1, 0, 'none');\n    fprintf('  P-only Kc = %.1f: y_ss = %.3f, offset = %.3f (theory %.3f)\\n', ...\n            KcP, yp(end), 1-yp(end), 1/(1+KcP));\nend\nfprintf('  -> dead time caps the gain: ultimate Kc ~ 2.9 here\\n\\n');\n\n% --- disturbance rejection: FB vs FF + FB ---\n[~, yfb] = closed_loop(Kc, tau_I, 0, 250, 0, 1, 'none');\n[~, yst] = closed_loop(Kc, tau_I, 0, 250, 0, 1, 'static');\n[~, yll] = closed_loop(Kc, tau_I, 0, 250, 0, 1, 'leadlag');\nfprintf('Unit disturbance step (setpoint = 0):\\n');\nfprintf('  feedback only          : max|y| = %.3f (lecture ~0.53)\\n', max(abs(yfb)));\nfprintf('  static FF + FB (heatex): max|y| = %.3f (lecture ~0.17)\\n', max(abs(yst)));\nfprintf('  exact -Gd/G FF + FB    : max|y| = %.3f\\n', max(abs(yll)));\n\nfunction [ts, ys] = closed_loop(Kc, tau_I, tau_D, T_end, setpoint, disturb, ff)\n    tau_p = 21.3; theta_p = 14.7; Kp = 1;\n    tau_d = 25.0; theta_d = 35.0;\n    dt = 0.01; n = round(T_end/dt);\n    dp = round(theta_p/dt); dd = round(theta_d/dt);\n    dst = round(25.0/dt); dll = round((theta_d-theta_p)/dt);\n    ubuf = zeros(1, n+dp+1); dbuf = zeros(1, n+dd+1);\n    fbuf = zeros(1, n+max(dst,dll)+1);\n    xff = 0; yp = 0; yd = 0; y = 0; I = 0; e_prev = setpoint;\n    ts = (0:n-1)*dt; ys = zeros(1, n);\n    for k = 1:n\n        e = setpoint - y;\n        I = I + e*dt;\n        u = Kc*(e + I/tau_I + tau_D*(e - e_prev)/dt);\n        e_prev = e;\n        if strcmp(ff, 'static')\n            fbuf(k+dst) = -disturb;  u = u + fbuf(k);\n        elseif strcmp(ff, 'leadlag')\n            xff = xff + dt*(disturb - xff)/tau_d;\n            fbuf(k+dll) = -(tau_p*(disturb - xff)/tau_d + xff);\n            u = u + fbuf(k);\n        end\n        ubuf(k+dp) = u;  dbuf(k+dd) = disturb;\n        yp = yp + dt*(-yp + Kp*ubuf(k))/tau_p;\n        yd = yd + dt*(-yd + dbuf(k))/tau_d;\n        y = yp + yd;  ys(k) = y;\n    end\nend\n",
    julia: "# Week 8 - Topic 2: PID Feedback & Feedforward Control of a Heat Exchanger\n# Plant (valve -> tank temperature), FOPDT: G = exp(-14.7 s)/(21.3 s + 1)\n# Disturbance (inflow temperature):       Gd = exp(-35 s)/(25 s + 1)\n# ITAE PI tuning: Kc = 0.859 (th/ta)^-0.977 = 1.2341,\n#                 tau_I = ta/0.674 (th/ta)^0.680 = 24.5582\n# Reproduces: setpoint overshoot ~1.26 near t~46 s; disturbance peak 0.53 (FB)\n# vs 0.17 (static FF + FB, the MATLAB 'heatex' demo configuration).\n\nusing Printf\n\nfunction closed_loop(Kc, tau_I; tau_D=0.0, T_end=250.0, setpoint=1.0,\n                     disturb=0.0, ff=:none)\n    tau_p, theta_p, Kp = 21.3, 14.7, 1.0\n    tau_d, theta_d = 25.0, 35.0\n    dt = 0.01; n = round(Int, T_end / dt)\n    dp = round(Int, theta_p / dt); dd = round(Int, theta_d / dt)\n    dst = round(Int, 25.0 / dt);   dll = round(Int, (theta_d - theta_p) / dt)\n    ubuf = zeros(n + dp + 1); dbuf = zeros(n + dd + 1)\n    fbuf = zeros(n + max(dst, dll) + 1)\n    xff = 0.0; yp = 0.0; yd = 0.0; y = 0.0; I = 0.0; e_prev = setpoint\n    ts = collect(0:n-1) .* dt; ys = zeros(n)\n    for k in 1:n\n        e = setpoint - y\n        I += e * dt\n        u = Kc * (e + I / tau_I + tau_D * (e - e_prev) / dt)\n        e_prev = e\n        if ff == :static\n            fbuf[k + dst] = -disturb; u += fbuf[k]\n        elseif ff == :leadlag\n            xff += dt * (disturb - xff) / tau_d\n            fbuf[k + dll] = -(tau_p * (disturb - xff) / tau_d + xff)\n            u += fbuf[k]\n        end\n        ubuf[k + dp] = u; dbuf[k + dd] = disturb\n        yp += dt * (-yp + Kp * ubuf[k]) / tau_p\n        yd += dt * (-yd + dbuf[k]) / tau_d\n        y = yp + yd; ys[k] = y\n    end\n    return ts, ys\nend\n\ntau_p, theta_p = 21.3, 14.7\nr = theta_p / tau_p\nKc = 0.859 * r^(-0.977)\ntau_I = tau_p / 0.674 * r^0.680\nprintln(\"ITAE PI tuning for G = exp(-14.7 s)/(21.3 s + 1):\")\n@printf(\"  Kc = %.4f (lecture 1.2341), tau_I = %.4f (lecture 24.5582)\\n\\n\", Kc, tau_I)\n\nts, ys = closed_loop(Kc, tau_I)\nymax, im = findmax(ys)\n@printf(\"Setpoint step (PI): peak y = %.3f at t = %.0f s (lecture ~1.26 @ 46 s)\\n\",\n        ymax, ts[im])\n@printf(\"  final y = %.4f -> no offset (integral action)\\n\\n\", ys[end])\n\nfor KcP in (0.5, 1.0, 2.0)\n    _, yp = closed_loop(KcP, 1e12; T_end=600.0)\n    @printf(\"  P-only Kc = %.1f: y_ss = %.3f, offset = %.3f (theory %.3f)\\n\",\n            KcP, yp[end], 1 - yp[end], 1 / (1 + KcP))\nend\nprintln(\"  -> dead time caps the gain: ultimate Kc ~ 2.9 here\\n\")\n\n_, yfb = closed_loop(Kc, tau_I; setpoint=0.0, disturb=1.0)\n_, yst = closed_loop(Kc, tau_I; setpoint=0.0, disturb=1.0, ff=:static)\n_, yll = closed_loop(Kc, tau_I; setpoint=0.0, disturb=1.0, ff=:leadlag)\nprintln(\"Unit disturbance step (setpoint = 0):\")\n@printf(\"  feedback only          : max|y| = %.3f (lecture ~0.53)\\n\", maximum(abs.(yfb)))\n@printf(\"  static FF + FB (heatex): max|y| = %.3f (lecture ~0.17)\\n\", maximum(abs.(yst)))\n@printf(\"  exact -Gd/G FF + FB    : max|y| = %.3f\\n\", maximum(abs.(yll)))\n",
    cpp: "// Week 8 - Topic 2: PID Feedback & Feedforward Control of a Heat Exchanger\n// Plant (valve -> tank temperature), FOPDT: G = exp(-14.7 s)/(21.3 s + 1)\n// Disturbance (inflow temperature):       Gd = exp(-35 s)/(25 s + 1)\n// ITAE PI tuning: Kc = 0.859 (th/ta)^-0.977 = 1.2341,\n//                 tau_I = ta/0.674 (th/ta)^0.680 = 24.5582\n// Reproduces: setpoint overshoot ~1.26 near t~46 s; disturbance peak 0.53 (FB)\n// vs 0.17 (static FF + FB, the MATLAB 'heatex' demo configuration).\n// Build: g++ -O2 -std=c++17 week8_topic2_pid_control.cpp -o pid && ./pid\n\n#include <cmath>\n#include <cstdio>\n#include <vector>\n#include <algorithm>\n#include <string>\n\nstd::vector<double> closed_loop(double Kc, double tau_I, double tau_D,\n                                double T_end, double setpoint, double disturb,\n                                const std::string& ff) {\n    const double tau_p = 21.3, theta_p = 14.7, Kp = 1.0;\n    const double tau_d = 25.0, theta_d = 35.0;\n    const double dt = 0.01;\n    const int n = static_cast<int>(T_end / dt);\n    const int dp = static_cast<int>(theta_p / dt);\n    const int dd = static_cast<int>(theta_d / dt);\n    const int dst = static_cast<int>(25.0 / dt);\n    const int dll = static_cast<int>((theta_d - theta_p) / dt);\n    std::vector<double> ubuf(n + dp + 1, 0.0), dbuf(n + dd + 1, 0.0);\n    std::vector<double> fbuf(n + std::max(dst, dll) + 1, 0.0);\n    double xff = 0, yp = 0, yd = 0, y = 0, I = 0, e_prev = setpoint;\n    std::vector<double> ys(n);\n    for (int k = 0; k < n; ++k) {\n        double e = setpoint - y;\n        I += e * dt;\n        double u = Kc * (e + I / tau_I + tau_D * (e - e_prev) / dt);\n        e_prev = e;\n        if (ff == \"static\") {\n            fbuf[k + dst] = -disturb;\n            u += fbuf[k];\n        } else if (ff == \"leadlag\") {\n            xff += dt * (disturb - xff) / tau_d;\n            fbuf[k + dll] = -(tau_p * (disturb - xff) / tau_d + xff);\n            u += fbuf[k];\n        }\n        ubuf[k + dp] = u;\n        dbuf[k + dd] = disturb;\n        yp += dt * (-yp + Kp * ubuf[k]) / tau_p;\n        yd += dt * (-yd + dbuf[k]) / tau_d;\n        y = yp + yd;\n        ys[k] = y;\n    }\n    return ys;\n}\n\ndouble max_abs(const std::vector<double>& v) {\n    double m = 0;\n    for (double x : v) m = std::max(m, std::fabs(x));\n    return m;\n}\n\nint main() {\n    const double tau_p = 21.3, theta_p = 14.7;\n    const double r = theta_p / tau_p;\n    const double Kc = 0.859 * std::pow(r, -0.977);\n    const double tau_I = tau_p / 0.674 * std::pow(r, 0.680);\n    std::printf(\"ITAE PI tuning for G = exp(-14.7 s)/(21.3 s + 1):\\n\");\n    std::printf(\"  Kc = %.4f (lecture 1.2341), tau_I = %.4f (lecture 24.5582)\\n\\n\",\n                Kc, tau_I);\n\n    auto ys = closed_loop(Kc, tau_I, 0, 250, 1, 0, \"none\");\n    int im = static_cast<int>(std::max_element(ys.begin(), ys.end()) - ys.begin());\n    std::printf(\"Setpoint step (PI): peak y = %.3f at t = %.0f s (lecture ~1.26 @ 46 s)\\n\",\n                ys[im], im * 0.01);\n    std::printf(\"  final y = %.4f -> no offset (integral action)\\n\\n\", ys.back());\n\n    for (double KcP : {0.5, 1.0, 2.0}) {\n        auto yp = closed_loop(KcP, 1e12, 0, 600, 1, 0, \"none\");\n        std::printf(\"  P-only Kc = %.1f: y_ss = %.3f, offset = %.3f (theory %.3f)\\n\",\n                    KcP, yp.back(), 1 - yp.back(), 1 / (1 + KcP));\n    }\n    std::printf(\"  -> dead time caps the gain: ultimate Kc ~ 2.9 here\\n\\n\");\n\n    auto yfb = closed_loop(Kc, tau_I, 0, 250, 0, 1, \"none\");\n    auto yst = closed_loop(Kc, tau_I, 0, 250, 0, 1, \"static\");\n    auto yll = closed_loop(Kc, tau_I, 0, 250, 0, 1, \"leadlag\");\n    std::printf(\"Unit disturbance step (setpoint = 0):\\n\");\n    std::printf(\"  feedback only          : max|y| = %.3f (lecture ~0.53)\\n\", max_abs(yfb));\n    std::printf(\"  static FF + FB (heatex): max|y| = %.3f (lecture ~0.17)\\n\", max_abs(yst));\n    std::printf(\"  exact -Gd/G FF + FB    : max|y| = %.3f\\n\", max_abs(yll));\n    return 0;\n}\n",
  },
  topic3: {
    title: "Planck's Law & Blackbody Radiation",
    python: "# Week 8 - Topic 3: Planck's Law, Wien's Displacement, Stefan-Boltzmann\n# Lecture (Part 2): counting standing-wave modes in a cavity gives the\n# density of states g(nu) dnu = 8 pi V nu^2 / c^3 dnu. Classical equipartition\n# (<E> = kB T) gives Rayleigh-Jeans and the ultraviolet catastrophe;\n# Planck's quantization E_n = n h nu gives\n#   <E> = h nu / (exp(h nu / kB T) - 1)\n# and the spectral flux F_lambda = (2 pi h c^2 / lambda^5) / (exp(hc/lambda kB T) - 1).\n# Results checked here:\n#   * total flux  F = sigma T^4 with sigma = 2 pi^5 kB^4/(15 h^3 c^2) = 5.670e-8\n#   * Wien peak   x e^x/(e^x - 1) = 5  -> x = 4.965 -> lambda_C T = 2.898e-3 m K\n#   * frequency peak: x = 2.821; sun at 5800 K peaks near 500 nm.\n\nimport math\n\nH = 6.62607015e-34     # J s\nC = 2.99792458e8       # m/s\nKB = 1.380649e-23      # J/K\n\n\ndef planck_lambda(lam, T):\n    \"\"\"Spectral emissive power F_lambda, W/m^2 per m of wavelength.\"\"\"\n    x = H * C / (lam * KB * T)\n    if x > 700:\n        return 0.0\n    return 2.0 * math.pi * H * C ** 2 / lam ** 5 / math.expm1(x)\n\n\ndef rayleigh_jeans(lam, T):\n    return 2.0 * math.pi * C * KB * T / lam ** 4\n\n\ndef solve_wien(target):\n    \"\"\"Solve x*exp(x)/(exp(x)-1) = target by bisection.\"\"\"\n    f = lambda x: x * math.exp(x) / math.expm1(x) - target\n    lo, hi = 0.5, 10.0\n    for _ in range(200):\n        mid = 0.5 * (lo + hi)\n        if f(lo) * f(mid) <= 0:\n            hi = mid\n        else:\n            lo = mid\n    return 0.5 * (lo + hi)\n\n\nif __name__ == \"__main__\":\n    # --- Stefan-Boltzmann constant from first principles ---\n    sigma = 2.0 * math.pi ** 5 * KB ** 4 / (15.0 * H ** 3 * C ** 2)\n    print(f\"sigma = 2 pi^5 kB^4/(15 h^3 c^2) = {sigma:.4e} W/m^2 K^4 (lecture 5.670e-8)\")\n\n    # numerical check of the Bose-Einstein integral int x^3/(e^x-1) dx = pi^4/15\n    n, xmax = 400000, 60.0\n    dx = xmax / n\n    integral = sum((i * dx + 0.5 * dx) ** 3 / math.expm1(i * dx + 0.5 * dx)\n                   for i in range(n)) * dx\n    print(f\"int_0^inf x^3/(e^x - 1) dx = {integral:.6f}  (pi^4/15 = {math.pi**4/15:.6f})\")\n\n    # --- Wien displacement (wavelength and frequency forms) ---\n    x5 = solve_wien(5.0)\n    x3 = solve_wien(3.0)\n    b = H * C / (x5 * KB)\n    print(f\"\\nWien (lambda form): x = {x5:.4f} (lecture 4.965) -> \"\n          f\"lambda_C T = {b*1e3:.4f} mm K (lecture 2.898)\")\n    print(f\"Wien (nu form)    : x = {x3:.4f} (lecture 2.821) -> nu_C = 2.821 kB T/h\")\n    for T, name in [(5800.0, \"Sun\"), (310.0, \"human body\"), (1500.0, \"furnace\")]:\n        lamC = b / T\n        print(f\"  {name:11s} T = {T:6.0f} K -> lambda_C = \"\n              f\"{lamC*1e9:8.1f} nm = {lamC*1e6:7.3f} um\")\n\n    # --- total flux: numerical integral of Planck vs sigma T^4 ---\n    T = 5800.0\n    lam_lo, lam_hi, nL = 10e-9, 100e-6, 20000\n    dlam = (lam_hi - lam_lo) / nL\n    F = sum(planck_lambda(lam_lo + (i + 0.5) * dlam, T) for i in range(nL)) * dlam\n    print(f\"\\nT = {T:.0f} K: integral of F_lambda = {F:.4e} W/m^2, \"\n          f\"sigma T^4 = {sigma*T**4:.4e} W/m^2\")\n\n    # --- Rayleigh-Jeans vs Planck: the ultraviolet catastrophe ---\n    print(\"\\nF_lambda at T = 2000 K (W/m^2 um):   lambda    Planck      Rayleigh-Jeans\")\n    for lam_um in (0.2, 0.5, 1.0, 1.449, 3.0, 10.0):\n        lam = lam_um * 1e-6\n        print(f\"  {lam_um:8.3f} um   {planck_lambda(lam, 2000.0)*1e-6:12.4e} \"\n              f\"{rayleigh_jeans(lam, 2000.0)*1e-6:14.4e}\")\n    print(\"  -> RJ diverges as lambda^-4 (catastrophe); Planck peaks at \"\n          f\"lambda_C = {b/2000.0*1e6:.3f} um for 2000 K and dies off exponentially.\")\n",
    matlab: "% Week 8 - Topic 3: Planck's Law, Wien's Displacement, Stefan-Boltzmann\n% Cavity mode counting: g(nu) dnu = 8 pi V nu^2/c^3 dnu.\n% Equipartition (<E> = kB T) -> Rayleigh-Jeans -> ultraviolet catastrophe.\n% Planck (E_n = n h nu) -> <E> = h nu/(exp(h nu/kB T) - 1) ->\n%   F_lambda = (2 pi h c^2/lambda^5)/(exp(hc/lambda kB T) - 1)\n% Checks: sigma = 2 pi^5 kB^4/(15 h^3 c^2) = 5.670e-8; Wien x = 4.965 ->\n% lambda_C T = 2.898e-3 m K; frequency form x = 2.821; Sun -> 500 nm.\n\nclear; clc;\n\nH = 6.62607015e-34; C = 2.99792458e8; KB = 1.380649e-23;\n\n% --- Stefan-Boltzmann constant ---\nsigma = 2*pi^5*KB^4 / (15*H^3*C^2);\nfprintf('sigma = %.4e W/m^2 K^4 (lecture 5.670e-8)\\n', sigma);\n\n% Bose-Einstein integral check: int x^3/(e^x - 1) = pi^4/15\nx = linspace(1e-6, 60, 400001);\nI = trapz(x, x.^3 ./ expm1(x));\nfprintf('int x^3/(e^x-1) dx = %.6f (pi^4/15 = %.6f)\\n\\n', I, pi^4/15);\n\n% --- Wien displacement: solve x e^x/(e^x - 1) = a by bisection ---\nx5 = solve_wien(5); x3 = solve_wien(3);\nb = H*C/(x5*KB);\nfprintf('Wien (lambda): x = %.4f (lecture 4.965) -> lambda_C T = %.4f mm K\\n', x5, b*1e3);\nfprintf('Wien (nu)    : x = %.4f (lecture 2.821) -> nu_C = 2.821 kB T/h\\n', x3);\nnames = {'Sun', 'human body', 'furnace'}; temps = [5800 310 1500];\nfor i = 1:3\n    fprintf('  %-11s T = %6.0f K -> lambda_C = %8.1f nm\\n', ...\n            names{i}, temps(i), b/temps(i)*1e9);\nend\n\n% --- total flux: numerical Planck integral vs sigma T^4 ---\nT = 5800;\nlam = linspace(10e-9, 100e-6, 20001);\nFlam = 2*pi*H*C^2 ./ lam.^5 ./ expm1(H*C ./ (lam*KB*T));\nfprintf('\\nT = %d K: integral F_lambda = %.4e, sigma T^4 = %.4e W/m^2\\n', ...\n        T, trapz(lam, Flam), sigma*T^4);\n\n% --- Rayleigh-Jeans vs Planck at 2000 K ---\nfprintf('\\nF_lambda at 2000 K (W/m^2 um):  lambda    Planck     Rayleigh-Jeans\\n');\nfor lam_um = [0.2 0.5 1.0 1.449 3.0 10.0]\n    l = lam_um*1e-6;\n    P  = 2*pi*H*C^2 / l^5 / expm1(H*C/(l*KB*2000));\n    RJ = 2*pi*C*KB*2000 / l^4;\n    fprintf('  %8.3f um  %12.4e  %14.4e\\n', lam_um, P*1e-6, RJ*1e-6);\nend\nfprintf('  -> RJ diverges as lambda^-4; Planck peaks at %.3f um and decays.\\n', ...\n        b/2000*1e6);\n\nfunction x = solve_wien(a)\n    f = @(x) x.*exp(x)./expm1(x) - a;\n    lo = 0.5; hi = 10;\n    for it = 1:200\n        mid = (lo + hi)/2;\n        if f(lo)*f(mid) <= 0, hi = mid; else, lo = mid; end\n    end\n    x = (lo + hi)/2;\nend\n",
    julia: "# Week 8 - Topic 3: Planck's Law, Wien's Displacement, Stefan-Boltzmann\n# Cavity mode counting: g(nu) dnu = 8 pi V nu^2/c^3 dnu.\n# Equipartition (<E> = kB T) -> Rayleigh-Jeans -> ultraviolet catastrophe.\n# Planck (E_n = n h nu) -> <E> = h nu/(exp(h nu/kB T) - 1) ->\n#   F_lambda = (2 pi h c^2/lambda^5)/(exp(hc/lambda kB T) - 1)\n# Checks: sigma = 2 pi^5 kB^4/(15 h^3 c^2) = 5.670e-8; Wien x = 4.965 ->\n# lambda_C T = 2.898e-3 m K; frequency form x = 2.821; Sun -> 500 nm.\n\nusing Printf\n\nconst H = 6.62607015e-34\nconst C = 2.99792458e8\nconst KB = 1.380649e-23\n\nplanck(lam, T) = 2pi * H * C^2 / lam^5 / expm1(H * C / (lam * KB * T))\nrayleigh_jeans(lam, T) = 2pi * C * KB * T / lam^4\n\nfunction solve_wien(a)\n    f(x) = x * exp(x) / expm1(x) - a\n    lo, hi = 0.5, 10.0\n    for _ in 1:200\n        mid = (lo + hi) / 2\n        f(lo) * f(mid) <= 0 ? (hi = mid) : (lo = mid)\n    end\n    return (lo + hi) / 2\nend\n\n# --- Stefan-Boltzmann constant ---\nsigma = 2 * pi^5 * KB^4 / (15 * H^3 * C^2)\n@printf(\"sigma = %.4e W/m^2 K^4 (lecture 5.670e-8)\\n\", sigma)\n\n# Bose-Einstein integral check\nn, xmax = 400_000, 60.0\ndx = xmax / n\nI = sum(((i + 0.5) * dx)^3 / expm1((i + 0.5) * dx) for i in 0:n-1) * dx\n@printf(\"int x^3/(e^x-1) dx = %.6f (pi^4/15 = %.6f)\\n\\n\", I, pi^4 / 15)\n\n# --- Wien displacement ---\nx5, x3 = solve_wien(5.0), solve_wien(3.0)\nb = H * C / (x5 * KB)\n@printf(\"Wien (lambda): x = %.4f (lecture 4.965) -> lambda_C T = %.4f mm K\\n\", x5, b * 1e3)\n@printf(\"Wien (nu)    : x = %.4f (lecture 2.821) -> nu_C = 2.821 kB T/h\\n\", x3)\nfor (name, T) in ((\"Sun\", 5800.0), (\"human body\", 310.0), (\"furnace\", 1500.0))\n    @printf(\"  %-11s T = %6.0f K -> lambda_C = %8.1f nm\\n\", name, T, b / T * 1e9)\nend\n\n# --- total flux check ---\nT = 5800.0\nlam_lo, lam_hi, nL = 10e-9, 100e-6, 20_000\ndlam = (lam_hi - lam_lo) / nL\nF = sum(planck(lam_lo + (i + 0.5) * dlam, T) for i in 0:nL-1) * dlam\n@printf(\"\\nT = %.0f K: integral F_lambda = %.4e, sigma T^4 = %.4e W/m^2\\n\",\n        T, F, sigma * T^4)\n\n# --- Rayleigh-Jeans vs Planck at 2000 K ---\nprintln(\"\\nF_lambda at 2000 K (W/m^2 um):  lambda    Planck     Rayleigh-Jeans\")\nfor lam_um in (0.2, 0.5, 1.0, 1.449, 3.0, 10.0)\n    l = lam_um * 1e-6\n    @printf(\"  %8.3f um  %12.4e  %14.4e\\n\", lam_um,\n            planck(l, 2000.0) * 1e-6, rayleigh_jeans(l, 2000.0) * 1e-6)\nend\n@printf(\"  -> RJ diverges as lambda^-4; Planck peaks at %.3f um and decays.\\n\",\n        b / 2000 * 1e6)\n",
    cpp: "// Week 8 - Topic 3: Planck's Law, Wien's Displacement, Stefan-Boltzmann\n// Cavity mode counting: g(nu) dnu = 8 pi V nu^2/c^3 dnu.\n// Equipartition (<E> = kB T) -> Rayleigh-Jeans -> ultraviolet catastrophe.\n// Planck (E_n = n h nu) -> <E> = h nu/(exp(h nu/kB T) - 1) ->\n//   F_lambda = (2 pi h c^2/lambda^5)/(exp(hc/lambda kB T) - 1)\n// Checks: sigma = 2 pi^5 kB^4/(15 h^3 c^2) = 5.670e-8; Wien x = 4.965 ->\n// lambda_C T = 2.898e-3 m K; frequency form x = 2.821; Sun -> 500 nm.\n// Build: g++ -O2 -std=c++17 week8_topic3_planck.cpp -o planck && ./planck\n\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n\nconst double H = 6.62607015e-34, C = 2.99792458e8, KB = 1.380649e-23;\n\ndouble planck(double lam, double T) {\n    double x = H * C / (lam * KB * T);\n    if (x > 700.0) return 0.0;\n    return 2.0 * M_PI * H * C * C / std::pow(lam, 5) / std::expm1(x);\n}\n\ndouble rayleigh_jeans(double lam, double T) {\n    return 2.0 * M_PI * C * KB * T / std::pow(lam, 4);\n}\n\ndouble solve_wien(double a) {\n    auto f = [a](double x) { return x * std::exp(x) / std::expm1(x) - a; };\n    double lo = 0.5, hi = 10.0;\n    for (int i = 0; i < 200; ++i) {\n        double mid = 0.5 * (lo + hi);\n        if (f(lo) * f(mid) <= 0) hi = mid; else lo = mid;\n    }\n    return 0.5 * (lo + hi);\n}\n\nint main() {\n    // --- Stefan-Boltzmann constant ---\n    const double sigma = 2.0 * std::pow(M_PI, 5) * std::pow(KB, 4) /\n                         (15.0 * std::pow(H, 3) * C * C);\n    std::printf(\"sigma = %.4e W/m^2 K^4 (lecture 5.670e-8)\\n\", sigma);\n\n    // Bose-Einstein integral check: int x^3/(e^x - 1) = pi^4/15\n    const int n = 400000;\n    const double xmax = 60.0, dx = xmax / n;\n    double I = 0.0;\n    for (int i = 0; i < n; ++i) {\n        double x = (i + 0.5) * dx;\n        I += x * x * x / std::expm1(x) * dx;\n    }\n    std::printf(\"int x^3/(e^x-1) dx = %.6f (pi^4/15 = %.6f)\\n\\n\",\n                I, std::pow(M_PI, 4) / 15.0);\n\n    // --- Wien displacement ---\n    const double x5 = solve_wien(5.0), x3 = solve_wien(3.0);\n    const double b = H * C / (x5 * KB);\n    std::printf(\"Wien (lambda): x = %.4f (lecture 4.965) -> lambda_C T = %.4f mm K\\n\",\n                x5, b * 1e3);\n    std::printf(\"Wien (nu)    : x = %.4f (lecture 2.821) -> nu_C = 2.821 kB T/h\\n\", x3);\n    const char* names[] = {\"Sun\", \"human body\", \"furnace\"};\n    const double temps[] = {5800.0, 310.0, 1500.0};\n    for (int i = 0; i < 3; ++i)\n        std::printf(\"  %-11s T = %6.0f K -> lambda_C = %8.1f nm\\n\",\n                    names[i], temps[i], b / temps[i] * 1e9);\n\n    // --- total flux check ---\n    const double T = 5800.0;\n    const double lam_lo = 10e-9, lam_hi = 100e-6;\n    const int nL = 20000;\n    const double dlam = (lam_hi - lam_lo) / nL;\n    double F = 0.0;\n    for (int i = 0; i < nL; ++i) F += planck(lam_lo + (i + 0.5) * dlam, T) * dlam;\n    std::printf(\"\\nT = %.0f K: integral F_lambda = %.4e, sigma T^4 = %.4e W/m^2\\n\",\n                T, F, sigma * std::pow(T, 4));\n\n    // --- Rayleigh-Jeans vs Planck at 2000 K ---\n    std::printf(\"\\nF_lambda at 2000 K (W/m^2 um):  lambda    Planck     Rayleigh-Jeans\\n\");\n    for (double lam_um : {0.2, 0.5, 1.0, 1.449, 3.0, 10.0}) {\n        double l = lam_um * 1e-6;\n        std::printf(\"  %8.3f um  %12.4e  %14.4e\\n\", lam_um,\n                    planck(l, 2000.0) * 1e-6, rayleigh_jeans(l, 2000.0) * 1e-6);\n    }\n    std::printf(\"  -> RJ diverges as lambda^-4; Planck peaks at %.3f um and decays.\\n\",\n                b / 2000.0 * 1e6);\n    return 0;\n}\n",
  },
  topic4: {
    title: "View Factors & Radiation Networks",
    python: "# Week 8 - Topic 4: View Factors & Gray-Surface Radiation Networks\n# Lecture (Part 2):\n#   * view factor F12 = fraction of energy leaving A1 that reaches A2;\n#     reciprocity A1 F12 = A2 F21, summation sum_j Fij = 1 (closed enclosure)\n#   * gray surface: radiosity J = rho G + eps Eb, surface resistance rho/(eps A),\n#     geometric resistance 1/(A1 F12)\n#   * n-surface system: (1 - Fii + eps_i/rho_i) J_i - sum_j J_j F_ij = (eps_i/rho_i) Eb_i\n# Reproduces the lecture 3-surface example (T1 = 1100 K, T2 = 550 K, T3 = 0 K,\n# A1 = 4 m^2):  black -> q1 = 328.3 kW;  gray (0.4/0.8/1) -> J1 = 33,900,\n# J2 = 5,510 W/m^2, q1 = 131.2 kW.  (The lecture uses sigma = 5.676e-8, the\n# classic Welty value; with the modern 5.670e-8 the answers shift by ~0.1%.)\n\nimport math\n\nSIGMA_LECTURE = 5.676e-8    # classic (Welty) value used in the lecture example\nSIGMA_MODERN = 5.670e-8\n\n\ndef f_parallel_rect(X, Y):\n    \"\"\"F12 for directly opposed parallel rectangles, X = a/c, Y = b/c.\"\"\"\n    x2, y2 = 1.0 + X * X, 1.0 + Y * Y\n    s = math.log(math.sqrt(x2 * y2 / (1.0 + X * X + Y * Y)))\n    s += X * math.sqrt(y2) * math.atan(X / math.sqrt(y2))\n    s += Y * math.sqrt(x2) * math.atan(Y / math.sqrt(x2))\n    s -= X * math.atan(X) + Y * math.atan(Y)\n    return 2.0 / (math.pi * X * Y) * s\n\n\ndef f_coaxial_disks(r1, r2, D):\n    \"\"\"F12 for coaxial parallel disks separated by D.\"\"\"\n    R1, R2 = r1 / D, r2 / D\n    X = 1.0 + (1.0 + R2 * R2) / (R1 * R1)\n    return 0.5 * (X - math.sqrt(X * X - 4.0 * (r2 / r1) ** 2))\n\n\ndef solve3(J, A, F, eps, Eb):\n    \"\"\"Gauss-Seidel solve of the 3-surface radiosity system (eps<1 surfaces).\"\"\"\n    for _ in range(500):\n        for i in range(3):\n            rho = 1.0 - eps[i]\n            if rho < 1e-12:                       # black: J = Eb\n                J[i] = Eb[i]\n                continue\n            c = eps[i] / rho\n            s = sum(F[i][j] * J[j] for j in range(3) if j != i)\n            J[i] = (c * Eb[i] + s) / (1.0 - F[i][i] + c)\n    return J\n\n\nif __name__ == \"__main__\":\n    # --- view-factor sanity checks against the lecture charts ---\n    print(\"View factors:\")\n    print(f\"  squares, side/distance = 1: F12 = {f_parallel_rect(1,1):.4f} (chart ~0.20)\")\n    print(f\"  squares, side/distance = 2: F12 = {f_parallel_rect(2,2):.4f} (chart ~0.41)\")\n    print(f\"  equal disks, r/D = 1      : F12 = {f_coaxial_disks(1,1,1):.4f} (chart ~0.38)\")\n    print(f\"  hemisphere over its base  : F12 = A2/A1 = 1/2 (reciprocity, lecture)\")\n    print(f\"  concentric spheres r1<r2  : F12 = 1, F21 = (r1/r2)^2, F22 = 1-(r1/r2)^2\")\n\n    # --- lecture 3-surface example ---\n    sig = SIGMA_LECTURE\n    T = [1100.0, 550.0, 0.0]\n    Eb = [sig * Ti ** 4 for Ti in T]\n    F = [[0.0, 0.2, 0.3], [0.2, 0.0, 0.8], [0.2, 0.2, 0.6]]\n    A1 = 4.0\n    print(f\"\\n3-surface enclosure (lecture): Eb1 = {Eb[0]:.0f}, Eb2 = {Eb[1]:.0f} W/m^2\")\n\n    # (a) all black\n    q1 = A1 * (Eb[0] - F[0][1] * Eb[1] - F[0][2] * Eb[2])\n    print(f\"  (a) all black:   q1 = A1(Eb1 - F12 Eb2 - F13 Eb3) = {q1/1e3:.1f} kW \"\n          \"(lecture 328.3)\")\n\n    # (b) surfaces 1,2 black, surface 3 re-radiating (q3 = 0)\n    J3 = (Eb[0] * F[2][0] + Eb[1] * F[2][1]) / (1.0 - F[2][2])\n    q1b = A1 * (Eb[0] - F[0][1] * Eb[1] - F[0][2] * J3)\n    q2b = A1 * (Eb[1] - F[1][0] * Eb[0] - F[1][2] * J3)   # A2 = A1 here\n    print(f\"  (b) 3 re-radiating: J3 = {J3:.0f} W/m^2, q1 = {q1b/1e3:.1f} kW, \"\n          f\"q2 = {q2b/1e3:.1f} kW\")\n    print(\"      -> surface 2 receives |q2| = \"\n          f\"{abs(q2b)/1e3:.1f} kW (the lecture's 187.0 kW figure)\")\n\n    # (c) gray: eps = (0.4, 0.8, 1.0)\n    eps = [0.4, 0.8, 1.0]\n    J = solve3([Eb[0], Eb[1], Eb[2]], A1, F, eps, Eb)\n    q1c = A1 * eps[0] / (1 - eps[0]) * (Eb[0] - J[0])\n    print(f\"  (c) gray (0.4/0.8/1): J1 = {J[0]:.0f} (lecture 33,900), \"\n          f\"J2 = {J[1]:.0f} (lecture 5,510) W/m^2\")\n    print(f\"      q1 = A1 eps1/rho1 (Eb1 - J1) = {q1c/1e3:.1f} kW (lecture 131.2)\")\n    print(f\"      (identical to A1[J1 - F12 J2 - F13 J3] = \"\n          f\"{A1*(J[0]-F[0][1]*J[1]-F[0][2]*J[2])/1e3:.1f} kW)\")\n\n    # --- radiation heat-transfer coefficient ---\n    T1, T2 = 400.0, 300.0\n    sig = SIGMA_MODERN\n    hr = 4.0 * sig * T1 ** 3                      # F12 = 1 limit, linearized at T1\n    q_exact = sig * (T1 ** 4 - T2 ** 4)\n    q_lin = hr * (T1 - T2)\n    print(f\"\\nRadiation coefficient h_r = 4 F12 sigma T1^3 (linearization):\")\n    print(f\"  T1 = {T1:.0f} K, T2 = {T2:.0f} K: h_r = {hr:.2f} W/m^2 K\")\n    print(f\"  exact sigma(T1^4-T2^4) = {q_exact:.0f} W/m^2 vs h_r dT = {q_lin:.0f} W/m^2\")\n    print(\"  -> the tangent-line estimate overshoots for large dT; \"\n          \"good only for T1 - T2 << T1.\")\n",
    matlab: "% Week 8 - Topic 4: View Factors & Gray-Surface Radiation Networks\n% View factor F12: fraction of energy leaving A1 that reaches A2;\n% reciprocity A1 F12 = A2 F21; summation sum_j Fij = 1 (closed enclosure).\n% Gray surface: radiosity J = rho G + eps Eb; resistances rho/(eps A), 1/(A F12).\n% n-surface system: (1 - Fii + eps_i/rho_i) J_i - sum_j J_j F_ij = (eps_i/rho_i) Eb_i\n% Reproduces the lecture 3-surface example (sigma = 5.676e-8, classic value):\n% black -> q1 = 328.3 kW; gray (0.4/0.8/1) -> J1 = 33,900, J2 = 5,510, q1 = 131.2 kW.\n\nclear; clc;\n\nSIGMA_LECTURE = 5.676e-8;  SIGMA_MODERN = 5.670e-8;\n\n% --- view-factor sanity checks against the lecture charts ---\nfprintf('View factors:\\n');\nfprintf('  squares side/dist = 1: F12 = %.4f (chart ~0.20)\\n', f_rect(1,1));\nfprintf('  squares side/dist = 2: F12 = %.4f (chart ~0.41)\\n', f_rect(2,2));\nfprintf('  equal disks r/D = 1  : F12 = %.4f (chart ~0.38)\\n', f_disks(1,1,1));\nfprintf('  hemisphere over base : F12 = 1/2 (reciprocity)\\n');\nfprintf('  concentric spheres   : F12 = 1, F21 = (r1/r2)^2\\n\\n');\n\n% --- lecture 3-surface example ---\nsig = SIGMA_LECTURE;\nT  = [1100 550 0];\nEb = sig * T.^4;\nF  = [0 0.2 0.3; 0.2 0 0.8; 0.2 0.2 0.6];\nA1 = 4;\nfprintf('3-surface enclosure: Eb1 = %.0f, Eb2 = %.0f W/m^2\\n', Eb(1), Eb(2));\n\n% (a) all black\nq1 = A1*(Eb(1) - F(1,2)*Eb(2) - F(1,3)*Eb(3));\nfprintf('  (a) all black: q1 = %.1f kW (lecture 328.3)\\n', q1/1e3);\n\n% (b) surfaces 1,2 black, surface 3 re-radiating (q3 = 0)\nJ3 = (Eb(1)*F(3,1) + Eb(2)*F(3,2)) / (1 - F(3,3));\nq1b = A1*(Eb(1) - F(1,2)*Eb(2) - F(1,3)*J3);\nq2b = A1*(Eb(2) - F(2,1)*Eb(1) - F(2,3)*J3);\nfprintf('  (b) 3 re-radiating: J3 = %.0f, q1 = %.1f kW, |q2| = %.1f kW (lecture 187.0)\\n', ...\n        J3, q1b/1e3, abs(q2b)/1e3);\n\n% (c) gray: eps = (0.4, 0.8, 1.0) -> Gauss-Seidel on the radiosity system\neps_ = [0.4 0.8 1.0];\nJ = Eb;\nfor it = 1:500\n    for i = 1:3\n        rho = 1 - eps_(i);\n        if rho < 1e-12, J(i) = Eb(i); continue; end\n        c = eps_(i)/rho;\n        s = F(i,:)*J' - F(i,i)*J(i);\n        J(i) = (c*Eb(i) + s) / (1 - F(i,i) + c);\n    end\nend\nq1c = A1*eps_(1)/(1-eps_(1))*(Eb(1) - J(1));\nfprintf('  (c) gray (0.4/0.8/1): J1 = %.0f (lect 33,900), J2 = %.0f (lect 5,510)\\n', ...\n        J(1), J(2));\nfprintf('      q1 = %.1f kW (lecture 131.2)\\n\\n', q1c/1e3);\n\n% --- radiation heat-transfer coefficient ---\nT1 = 400; T2 = 300; sig = SIGMA_MODERN;\nhr = 4*sig*T1^3;\nfprintf('h_r = 4 sigma T1^3 = %.2f W/m^2 K (T1 = 400 K)\\n', hr);\nfprintf('exact sigma(T1^4-T2^4) = %.0f vs h_r dT = %.0f W/m^2\\n', ...\n        sig*(T1^4 - T2^4), hr*(T1 - T2));\nfprintf('-> linearization good only for T1 - T2 << T1\\n');\n\nfunction F12 = f_rect(X, Y)\n    % directly opposed parallel rectangles, X = a/c, Y = b/c\n    x2 = 1 + X^2; y2 = 1 + Y^2;\n    s = log(sqrt(x2*y2/(1 + X^2 + Y^2))) ...\n      + X*sqrt(y2)*atan(X/sqrt(y2)) + Y*sqrt(x2)*atan(Y/sqrt(x2)) ...\n      - X*atan(X) - Y*atan(Y);\n    F12 = 2/(pi*X*Y) * s;\nend\n\nfunction F12 = f_disks(r1, r2, D)\n    R1 = r1/D; R2 = r2/D;\n    X = 1 + (1 + R2^2)/R1^2;\n    F12 = 0.5*(X - sqrt(X^2 - 4*(r2/r1)^2));\nend\n",
    julia: "# Week 8 - Topic 4: View Factors & Gray-Surface Radiation Networks\n# View factor F12: fraction of energy leaving A1 that reaches A2;\n# reciprocity A1 F12 = A2 F21; summation sum_j Fij = 1 (closed enclosure).\n# Gray surface: radiosity J = rho G + eps Eb; resistances rho/(eps A), 1/(A F12).\n# n-surface system: (1 - Fii + eps_i/rho_i) J_i - sum_j J_j F_ij = (eps_i/rho_i) Eb_i\n# Reproduces the lecture 3-surface example (sigma = 5.676e-8, classic value):\n# black -> q1 = 328.3 kW; gray (0.4/0.8/1) -> J1 = 33,900, J2 = 5,510, q1 = 131.2 kW.\n\nusing Printf\n\nconst SIGMA_LECTURE = 5.676e-8\nconst SIGMA_MODERN = 5.670e-8\n\nfunction f_rect(X, Y)   # directly opposed parallel rectangles, X = a/c, Y = b/c\n    x2, y2 = 1 + X^2, 1 + Y^2\n    s = log(sqrt(x2 * y2 / (1 + X^2 + Y^2)))\n    s += X * sqrt(y2) * atan(X / sqrt(y2)) + Y * sqrt(x2) * atan(Y / sqrt(x2))\n    s -= X * atan(X) + Y * atan(Y)\n    return 2 / (pi * X * Y) * s\nend\n\nfunction f_disks(r1, r2, D)\n    R1, R2 = r1 / D, r2 / D\n    X = 1 + (1 + R2^2) / R1^2\n    return 0.5 * (X - sqrt(X^2 - 4 * (r2 / r1)^2))\nend\n\nfunction solve3!(J, F, eps_, Eb)\n    for _ in 1:500, i in 1:3\n        rho = 1 - eps_[i]\n        if rho < 1e-12\n            J[i] = Eb[i]\n            continue\n        end\n        c = eps_[i] / rho\n        s = sum(F[i, j] * J[j] for j in 1:3 if j != i)\n        J[i] = (c * Eb[i] + s) / (1 - F[i, i] + c)\n    end\n    return J\nend\n\n# --- view-factor sanity checks ---\nprintln(\"View factors:\")\n@printf(\"  squares side/dist = 1: F12 = %.4f (chart ~0.20)\\n\", f_rect(1, 1))\n@printf(\"  squares side/dist = 2: F12 = %.4f (chart ~0.41)\\n\", f_rect(2, 2))\n@printf(\"  equal disks r/D = 1  : F12 = %.4f (chart ~0.38)\\n\", f_disks(1, 1, 1))\nprintln(\"  hemisphere over base : F12 = 1/2 (reciprocity)\")\nprintln(\"  concentric spheres   : F12 = 1, F21 = (r1/r2)^2\\n\")\n\n# --- lecture 3-surface example ---\nsig = SIGMA_LECTURE\nT = [1100.0, 550.0, 0.0]\nEb = sig .* T .^ 4\nF = [0.0 0.2 0.3; 0.2 0.0 0.8; 0.2 0.2 0.6]\nA1 = 4.0\n@printf(\"3-surface enclosure: Eb1 = %.0f, Eb2 = %.0f W/m^2\\n\", Eb[1], Eb[2])\n\nq1 = A1 * (Eb[1] - F[1, 2] * Eb[2] - F[1, 3] * Eb[3])\n@printf(\"  (a) all black: q1 = %.1f kW (lecture 328.3)\\n\", q1 / 1e3)\n\nJ3 = (Eb[1] * F[3, 1] + Eb[2] * F[3, 2]) / (1 - F[3, 3])\nq1b = A1 * (Eb[1] - F[1, 2] * Eb[2] - F[1, 3] * J3)\nq2b = A1 * (Eb[2] - F[2, 1] * Eb[1] - F[2, 3] * J3)\n@printf(\"  (b) 3 re-radiating: J3 = %.0f, q1 = %.1f kW, |q2| = %.1f kW (lecture 187.0)\\n\",\n        J3, q1b / 1e3, abs(q2b) / 1e3)\n\neps_ = [0.4, 0.8, 1.0]\nJ = solve3!(copy(Eb), F, eps_, Eb)\nq1c = A1 * eps_[1] / (1 - eps_[1]) * (Eb[1] - J[1])\n@printf(\"  (c) gray (0.4/0.8/1): J1 = %.0f (lect 33,900), J2 = %.0f (lect 5,510)\\n\",\n        J[1], J[2])\n@printf(\"      q1 = %.1f kW (lecture 131.2)\\n\\n\", q1c / 1e3)\n\n# --- radiation heat-transfer coefficient ---\nT1, T2 = 400.0, 300.0\nsig = SIGMA_MODERN\nhr = 4 * sig * T1^3\n@printf(\"h_r = 4 sigma T1^3 = %.2f W/m^2 K (T1 = 400 K)\\n\", hr)\n@printf(\"exact sigma(T1^4-T2^4) = %.0f vs h_r dT = %.0f W/m^2\\n\",\n        sig * (T1^4 - T2^4), hr * (T1 - T2))\nprintln(\"-> linearization good only for T1 - T2 << T1\")\n",
    cpp: "// Week 8 - Topic 4: View Factors & Gray-Surface Radiation Networks\n// View factor F12: fraction of energy leaving A1 that reaches A2;\n// reciprocity A1 F12 = A2 F21; summation sum_j Fij = 1 (closed enclosure).\n// Gray surface: radiosity J = rho G + eps Eb; resistances rho/(eps A), 1/(A F12).\n// n-surface system: (1 - Fii + eps_i/rho_i) J_i - sum_j J_j F_ij = (eps_i/rho_i) Eb_i\n// Reproduces the lecture 3-surface example (sigma = 5.676e-8, classic value):\n// black -> q1 = 328.3 kW; gray (0.4/0.8/1) -> J1 = 33,900, J2 = 5,510, q1 = 131.2 kW.\n// Build: g++ -O2 -std=c++17 week8_topic4_radiation_network.cpp -o radnet && ./radnet\n\n#include <cmath>\n#include <cstdio>\n#include <array>\n\nconst double SIGMA_LECTURE = 5.676e-8;\nconst double SIGMA_MODERN = 5.670e-8;\n\n// directly opposed parallel rectangles, X = a/c, Y = b/c\ndouble f_rect(double X, double Y) {\n    double x2 = 1 + X * X, y2 = 1 + Y * Y;\n    double s = std::log(std::sqrt(x2 * y2 / (1 + X * X + Y * Y)));\n    s += X * std::sqrt(y2) * std::atan(X / std::sqrt(y2));\n    s += Y * std::sqrt(x2) * std::atan(Y / std::sqrt(x2));\n    s -= X * std::atan(X) + Y * std::atan(Y);\n    return 2.0 / (M_PI * X * Y) * s;\n}\n\ndouble f_disks(double r1, double r2, double D) {\n    double R1 = r1 / D, R2 = r2 / D;\n    double X = 1 + (1 + R2 * R2) / (R1 * R1);\n    return 0.5 * (X - std::sqrt(X * X - 4 * (r2 / r1) * (r2 / r1)));\n}\n\nint main() {\n    std::printf(\"View factors:\\n\");\n    std::printf(\"  squares side/dist = 1: F12 = %.4f (chart ~0.20)\\n\", f_rect(1, 1));\n    std::printf(\"  squares side/dist = 2: F12 = %.4f (chart ~0.41)\\n\", f_rect(2, 2));\n    std::printf(\"  equal disks r/D = 1  : F12 = %.4f (chart ~0.38)\\n\", f_disks(1, 1, 1));\n    std::printf(\"  hemisphere over base : F12 = 1/2 (reciprocity)\\n\");\n    std::printf(\"  concentric spheres   : F12 = 1, F21 = (r1/r2)^2\\n\\n\");\n\n    // --- lecture 3-surface example ---\n    double sig = SIGMA_LECTURE;\n    std::array<double, 3> T = {1100.0, 550.0, 0.0};\n    std::array<double, 3> Eb;\n    for (int i = 0; i < 3; ++i) Eb[i] = sig * std::pow(T[i], 4);\n    double F[3][3] = {{0.0, 0.2, 0.3}, {0.2, 0.0, 0.8}, {0.2, 0.2, 0.6}};\n    const double A1 = 4.0;\n    std::printf(\"3-surface enclosure: Eb1 = %.0f, Eb2 = %.0f W/m^2\\n\", Eb[0], Eb[1]);\n\n    // (a) all black\n    double q1 = A1 * (Eb[0] - F[0][1] * Eb[1] - F[0][2] * Eb[2]);\n    std::printf(\"  (a) all black: q1 = %.1f kW (lecture 328.3)\\n\", q1 / 1e3);\n\n    // (b) surfaces 1,2 black, surface 3 re-radiating (q3 = 0)\n    double J3 = (Eb[0] * F[2][0] + Eb[1] * F[2][1]) / (1.0 - F[2][2]);\n    double q1b = A1 * (Eb[0] - F[0][1] * Eb[1] - F[0][2] * J3);\n    double q2b = A1 * (Eb[1] - F[1][0] * Eb[0] - F[1][2] * J3);\n    std::printf(\"  (b) 3 re-radiating: J3 = %.0f, q1 = %.1f kW, |q2| = %.1f kW \"\n                \"(lecture 187.0)\\n\", J3, q1b / 1e3, std::fabs(q2b) / 1e3);\n\n    // (c) gray: eps = (0.4, 0.8, 1.0) -> Gauss-Seidel\n    std::array<double, 3> eps = {0.4, 0.8, 1.0};\n    std::array<double, 3> J = Eb;\n    for (int it = 0; it < 500; ++it) {\n        for (int i = 0; i < 3; ++i) {\n            double rho = 1.0 - eps[i];\n            if (rho < 1e-12) { J[i] = Eb[i]; continue; }\n            double c = eps[i] / rho;\n            double s = 0.0;\n            for (int j = 0; j < 3; ++j) if (j != i) s += F[i][j] * J[j];\n            J[i] = (c * Eb[i] + s) / (1.0 - F[i][i] + c);\n        }\n    }\n    double q1c = A1 * eps[0] / (1.0 - eps[0]) * (Eb[0] - J[0]);\n    std::printf(\"  (c) gray (0.4/0.8/1): J1 = %.0f (lect 33,900), J2 = %.0f \"\n                \"(lect 5,510)\\n\", J[0], J[1]);\n    std::printf(\"      q1 = %.1f kW (lecture 131.2)\\n\\n\", q1c / 1e3);\n\n    // --- radiation heat-transfer coefficient ---\n    double T1 = 400.0, T2 = 300.0;\n    sig = SIGMA_MODERN;\n    double hr = 4.0 * sig * std::pow(T1, 3);\n    std::printf(\"h_r = 4 sigma T1^3 = %.2f W/m^2 K (T1 = 400 K)\\n\", hr);\n    std::printf(\"exact sigma(T1^4-T2^4) = %.0f vs h_r dT = %.0f W/m^2\\n\",\n                sig * (std::pow(T1, 4) - std::pow(T2, 4)), hr * (T1 - T2));\n    std::printf(\"-> linearization good only for T1 - T2 << T1\\n\");\n    return 0;\n}\n",
  },
};

export default WEEK8_CODES;
